void dm_ui_gen_bump(int why) { (void)why; }   // 界面代号（dm_cursor.c）：单测不管 | UI generation (dm_cursor.c): not relevant to unit tests
static int checks, fails;
#define CHECK(c, s) do { checks++; int ok = !!(c); fails += !ok; printf("%s %s\n", ok ? "✓" : "✗", s); } while (0)
static void reset(void) { g_mqh = g_mqn = 0; g_focus = 1; g_opmode = 1; g_ntf_opmode = g_ntf_perfmode = 0; }
static int pop_is(uint32_t want) { uint32_t m = 999; return h_oe_TryPopMsg(&m) && m == want; }
static int empty(void) { uint32_t m = 999; return !h_oe_TryPopMsg(&m) && m == 999; }
static int child_kind;
static void abort_exit(int sig) { (void)sig; dprintf(2, "【红】t_oe child kind=%d：10 秒看门狗超时\n", child_kind); _exit(97); } // 子进程旧版die可核，避免产生崩溃报告或core | the old-version die in the child process can be checked, avoiding a crash report or core
static void *focus_burst(void *p) { (void)p; for (int i = 0; i < 17; i++) { dm_focus_set(2); dm_focus_set(1); } return NULL; }
static void *mode_burst(void *p) { (void)p; for (int i = 0; i < 17; i++) dm_set_opmode(i % 2); return NULL; }
static pthread_mutex_t stage_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t stage_cond = PTHREAD_COND_INITIALIZER;
static int stage, interleaved_ok;
static void stage_set(int n) { pthread_mutex_lock(&stage_lock); stage = n; pthread_cond_broadcast(&stage_cond); pthread_mutex_unlock(&stage_lock); }
static void stage_wait(int n) { pthread_mutex_lock(&stage_lock); while (stage < n) pthread_cond_wait(&stage_cond, &stage_lock); pthread_mutex_unlock(&stage_lock); }
static void *consume_interleaved(void *p) {
    (void)p; stage_wait(1); int ok = pop_is(15); stage_set(2); // 已弹出，尚未查询：精确让生产者在此更新 | popped but not yet queried: let the producer update exactly here
    stage_wait(3); interleaved_ok = ok && h_oe_GetFocus() == 1 && pop_is(15) && pop_is(30) && pop_is(31) && empty() && h_oe_GetOpMode() == 0 && h_oe_GetPerfMode() == 0;
    return NULL;
}
static int child_burst(int kind) {
    fflush(stdout); pid_t p = fork(); if (p < 0) return 0;
    if (!p) {
        child_kind = kind; signal(SIGABRT, abort_exit); signal(SIGALRM, abort_exit); alarm(10); reset();
        g_ntf_opmode = g_ntf_perfmode = 1;
        if (kind == 0) { focus_burst(NULL); _exit(h_oe_GetFocus() == 1 && pop_is(15) && empty() ? 0 : 1); }
        if (kind == 1) { mode_burst(NULL); _exit(h_oe_GetOpMode() == 0 && h_oe_GetPerfMode() == 0 && pop_is(30) && pop_is(31) && empty() ? 0 : 1); }
        if (kind == 3) {
            pthread_t c; pthread_create(&c, NULL, consume_interleaved, NULL);
            dm_focus_set(2); stage_set(1); stage_wait(2);
            dm_focus_set(1); dm_set_opmode(0); stage_set(3); pthread_join(c, NULL);
            _exit(interleaved_ok ? 0 : 1);
        }
        pthread_t f, m; pthread_create(&f, NULL, focus_burst, NULL); pthread_create(&m, NULL, mode_burst, NULL);
        pthread_join(f, NULL); pthread_join(m, NULL);
        uint32_t msg; int nf = 0, no = 0, np = 0, order = 1;
        while (h_oe_TryPopMsg(&msg)) { if (msg == 15) nf++; else if (msg == 30) no++; else if (msg == 31) { order &= no == 1; np++; } else order = 0; }
        _exit(nf == 1 && no == 1 && np == 1 && order && h_oe_GetFocus() == 1 && h_oe_GetOpMode() == 0 ? 0 : 1);
    }
    int st; if (waitpid(p, &st, 0) != p) return 0;
    return WIFEXITED(st) && WEXITSTATUS(st) == 0;
}
// Dynamic 3D scale controller (scale3d_ctl_step, pure function): expected values are worked out by hand from the rules, not generated by the
// implementation. Rules (hle_oe.c):
// - a dropped frame = interval > 1.5 x the period + 0.25 ms (25.25 ms at 60 fps) or -1 (not shown); one window per 2 s; lower = dropped-frame rate over
//   the last 5 windows > 5% or over the last 30 windows > 1.5%; raise = 15 consecutive windows with zero drops;
// - after a level change, judging pauses 3 s and the history is cleared; lowered again within 15 s of a raise -> the next raise needs 45 windows;
// - a run of drops counts its first 3 frames, and every frame once it has lasted 1 s with a late frame on screen in it; a run of only frames not
//   shown never escalates (R1); a window with no frame on screen is neither judged nor clean (R2).
static uint64_t s3_now; static scale3d_ctl s3; static int s3_dm;   // s3_dm：累计换级次数 | s3_dm: cumulative number of level changes
static int s3_one(double iv) { int b = s3.level; s3_now += (uint64_t)((iv > 0 ? iv : 16.6667) * 1e6); int lv = scale3d_ctl_step(&s3, iv, s3_now); s3_dm += lv != b; return lv; }
static int s3_n(int n, double iv) { int lv = s3.level; for (int i = 0; i < n; i++) lv = s3_one(iv); return lv; }
#define F60 16.6667   // 60 帧：每窗 120 帧（120 × 16.6667 = 2000.004 ms） | 60 fps: 120 frames per window (120 * 16.6667 = 2000.004 ms)
#define D60 33.4      // a dropped frame (> 25.25 ms): with every frame dropped, 60 frames per window (60 x 33.4 = 2004 ms)
static void s3_hold_pass(void) { uint64_t end = s3.hold_until; while (s3_now < end) s3_one(F60); }   // 走完停判（停判中的帧不计） | Run through the judging pause (frames during the pause are not counted)
// 真机实玩第二段每 10 秒窗的「25 ms 档 / ≥33 ms 档」帧数（手抄自 perf 行）
// Frame counts of the "25 ms bucket / >=33 ms bucket" for each 10-second window of the second section of real play on a real device (copied by hand from perf lines)
static const int s3_rows[18][2] = {{0,1},{2,4},{3,3},{0,0},{10,12},{0,0},{0,0},{0,0},{2,1},{0,0},{6,8},{0,0},{0,0},{0,0},{2,3},{5,4},{0,0},{0,0}};
static int s3_replay(int clustered) {   // clustered = 1：每 10 秒的慢帧挤在开头连续出现（最坏情况）；0：均匀散开。返回换级次数 | clustered = 1: the slow frames of each 10 seconds are packed consecutively at the start (worst case); 0: spread evenly. Returns the number of level changes
    s3 = (scale3d_ctl){.max_level = 3}; s3_now = 5000 * S3_SEC; s3_dm = 0;
    for (int r = 0; r < 18; r++) { int ns = s3_rows[r][0] + s3_rows[r][1], every = ns ? 600 / ns : 0;
        for (int i = 0; i < 600; i++) { int slow = clustered ? i < ns : (ns && i % every == 0 && i / every < ns); s3_one(slow ? (i % 2 ? 25.0 : 40.0) : F60); } }
    return s3_dm;
}
static void test_scale3d(void) {
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 1000 * S3_SEC;
    CHECK(s3_n(1200, F60) == 0, "动态比例：60 帧稳 20 秒 → 保持 0 档");
    CHECK(s3_n(1000, 25.0) == 0, "dynamic scale: 25.0 ms (not over 25.25) is not a drop: no step");
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 1100 * S3_SEC;
    CHECK(s3_n(299, D60) == 0, "快降：全掉帧 4 窗多 1 帧不到（不足 5 窗）→ 还没降");
    CHECK(s3_n(1, D60) == 1, "快降：满 5 窗（10 秒）掉帧率 100% > 5% → 降到 1 档");
    s3_hold_pass();
    CHECK(s3.level == 1, "快降：停判 3 秒内的帧不计");
    CHECK(s3_n(299, D60) == 1 && s3_n(1, D60) == 2, "快降：停判后历史清空，再满 5 窗 → 降到 2 档");
    s3_hold_pass();
    CHECK(s3_n(3000, D60) == 2, "下限：已到第 2 档（max_level），再掉也不动");
    // Levels (dm_s3lv.h): up to three steps of x0.93 below the configured value, rounded to hundredths, never below 0.50
#define LV(cfg, lv, want) (fabsf(s3_level_scale(cfg, lv) - (want)) < 1e-4f)
    CHECK(s3_max_level(0.75f, 0) == 3 && LV(0.75f, 0, 0.75f) && LV(0.75f, 1, 0.70f) && LV(0.75f, 2, 0.65f) && LV(0.75f, 3, 0.60f), "levels: 75% -> 0.70 / 0.65 / 0.60 (as before)");
#if S3_FIRST_AT_FULL == 1
    CHECK(s3_max_level(1.0f, 0) == 3 && LV(1.0f, 1, 0.93f) && LV(1.0f, 2, 0.86f) && LV(1.0f, 3, 0.80f), "levels: 100% -> 0.93 / 0.86 / 0.80 (S3_FIRST_AT_FULL 1)");
#else   // the exit ABBA's other outcome: the first step at 95% or more is 0.86
    CHECK(s3_max_level(1.0f, 0) == 3 && LV(1.0f, 1, 0.86f) && LV(1.0f, 2, 0.80f) && LV(1.0f, 3, 0.75f), "levels: 100% -> 0.86 / 0.80 / 0.75 (S3_FIRST_AT_FULL 2)");
#endif
    CHECK(s3_max_level(0.85f, 0) == 3 && LV(0.85f, 1, 0.79f) && LV(0.85f, 2, 0.74f) && LV(0.85f, 3, 0.68f), "levels: 85% -> 0.79 / 0.74 / 0.68");
    CHECK(s3_max_level(0.67f, 0) == 3 && LV(0.67f, 1, 0.62f) && LV(0.67f, 2, 0.58f) && LV(0.67f, 3, 0.54f), "levels: 67% -> 0.62 / 0.58 / 0.54");
    CHECK(s3_max_level(0.5f, 0) == 0 && dm_3d_scale_levels(0.5f) == 0, "levels: 50% -> none");
    CHECK(s3_max_level(0.55f, 0) == 1 && LV(0.55f, 1, 0.51f), "levels: 55% -> one (0.51)");
    CHECK(s3_max_level(1.0f, 0.60f) == 8 - S3_FIRST_AT_FULL && LV(1.0f, 8 - S3_FIRST_AT_FULL, 0.60f), "levels: DM_3D_SCALE_FLOOR=0.60 at 100% -> down to 0.60 (7 levels with S3_FIRST_AT_FULL 1)");
    // The floor is compared with the scale a level runs at (rounded): 0.75 x 0.93 = 0.6975 runs at 0.70, so a floor of 0.70 keeps that level
    CHECK(s3_max_level(0.75f, 0.70f) == 1 && LV(0.75f, 1, 0.70f), "levels: DM_3D_SCALE_FLOOR=0.70 at 75% -> one level, 0.70");
    CHECK(s3_max_level(0.75f, 0.65f) == 2 && LV(0.75f, 2, 0.65f), "levels: DM_3D_SCALE_FLOOR=0.65 at 75% -> 0.70 / 0.65");
    CHECK(s3_max_level(0.62f, 0) == 3 && LV(0.62f, 3, 0.50f), "levels: 62% (DM_3D_SCALE) -> 0.58 / 0.54 / 0.50, the last one at the floor");
    CHECK(LV(0.75f, 10, 0.50f), "levels: past the last one the scale is clamped at 0.50");
    CHECK(dm_3d_scale_levels(1.0f) == 3 && dm_3d_scale_levels(0.67f) == 3 && dm_3d_scale_levels(0.75f) == 3, "dm_3d_scale_levels: 3 at 100%, 75% and 67%");
    // A new configured value (the 3D Resolution setting applied): the deepest level is recomputed for it, back to level 0, judging paused 3 s;
    // drops after that stop at its last level
    s3 = (scale3d_ctl){.max_level = s3_max_level(1.0f, 0), .level = 2}; s3_now = 1500 * S3_SEC;
    scale3d_ctl_retarget(&s3, 0.75f, 0, s3_now);
    CHECK(s3.max_level == 3 && s3.level == 0 && s3.hold_until == s3_now + 3 * S3_SEC, "retarget 100% -> 75%: 3 levels, from level 2 back to 0, judging held 3 s");
    s3_hold_pass(); s3_n(6000, D60);
    CHECK(s3.level == 3 && LV(0.75f, s3.level, 0.60f), "after retargeting, constant drops stop at level 3 (0.60)");
    scale3d_ctl_retarget(&s3, 1.0f, 0, s3_now);
    CHECK(s3.max_level == 3 && s3.level == 0, "retarget back to 100%: 3 levels, level 0");
    // 慢降：每窗 3 帧掉帧 + 114 帧正常（3 × 33.4 + 114 × 16.6667 = 2000.2 ms，一窗 117 帧，掉帧率 2.56%）
    // Slow lowering: per window 3 dropped frames + 114 normal frames (3 × 33.4 + 114 × 16.6667 = 2000.2 ms, 117 frames per window, dropped-frame rate 2.56%)
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 2000 * S3_SEC;
    for (int w = 0; w < 29; w++) { s3_n(3, D60); s3_n(114, F60); }
    CHECK(s3.level == 0, "慢降：2.56% 的窗 29 个（不到 60 秒；10 秒内 2.56% < 5%）→ 不降");
    s3_n(3, D60); s3_n(114, F60);
    CHECK(s3.level == 1, "慢降：满 30 窗（60 秒）掉帧率 2.56% > 1.5% → 降到 1 档");
    // 升档：从 2 档、零掉帧
    // Raise: from level 2, zero dropped frames
    s3 = (scale3d_ctl){.max_level = 2, .level = 2}; s3_now = 3000 * S3_SEC;
    CHECK(s3_n(1799, F60) == 2, "升档：零掉帧 14 窗多 → 还不升");
    CHECK(s3_n(1, F60) == 1, "升档：连续 15 窗（30 秒）零掉帧 → 升到 1 档");
    s3 = (scale3d_ctl){.max_level = 2, .level = 2}; s3_now = 3500 * S3_SEC;
    s3_n(1500, F60); s3_one(D60); 
    CHECK(s3_n(1500, F60) == 2, "升档：中途一帧掉帧把连续计数清零 → 30 秒内不升");
    // 防抖：刚升上去 15 秒内又被打回 → 下一次升要 45 窗
    // Debounce: knocked back within 15 s of being raised → the next raise needs 45 windows
    s3 = (scale3d_ctl){.max_level = 2, .level = 1}; s3_now = 4000 * S3_SEC;
    CHECK(s3_n(1800, F60) == 0, "防抖：30 秒零掉帧 → 升到 0 档");
    s3_hold_pass();
    CHECK(s3_n(300, D60) == 1, "防抖：升上去约 13 秒内满 5 窗全掉帧 → 打回 1 档");
    s3_hold_pass();
    CHECK(s3_n(120 * 43, F60) == 1, "防抖：刚升又掉，之后零掉帧 43 窗（86 秒）→ 不升（要 45 窗）");
    CHECK(s3_n(120 * 3, F60) == 0, "防抖：满 45 窗 → 升到 0 档");
    // 被系统丢弃（−1）算掉帧；无读数（0）不计
    // Discarded by the system (−1) counts as a dropped frame; no reading (0) is not counted
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 5500 * S3_SEC; int lv = 0;
    for (int i = 0; i < 599; i++) lv = s3_one(i % 2 ? -1 : F60);
    CHECK(lv == 0, "丢弃帧：一半帧被丢弃，不足 5 窗 → 还没降");
    CHECK(s3_one(-1) == 1, "丢弃帧：满 5 窗、掉帧率 50% → 降到 1 档");
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 5800 * S3_SEC;
    CHECK(s3_n(5000, 0) == 0, "无读数（0）的帧不计 → 不动");
    // 30 帧档：周期 33.33，掉 50 ms
    // 30 fps level: period 33.33, a drop is 50 ms
    s3 = (scale3d_ctl){.max_level = 2, .period_ms = 1000.0 / 30}; s3_now = 6000 * S3_SEC;
    CHECK(s3_n(600, 33.34) == 0, "30 帧档：33.34 ms 稳 20 秒 → 保持 0 档");
    CHECK(s3_n(1000, 45.0) == 0, "30 帧档：45 ms（未超 50）不算掉帧");
    s3 = (scale3d_ctl){.max_level = 2, .period_ms = 1000.0 / 30}; s3_now = 6500 * S3_SEC;   // 新起：不带上一段留在窗里的半个窗 | Fresh start: does not carry the half window left over from the previous segment
    CHECK(s3_n(149, 66.7) == 0 && s3_n(1, 66.7) == 1, "30 帧档：66.7 ms 全掉帧满 5 窗（每窗 30 帧 = 2001 ms，共 150 帧）→ 降到 1 档");
    // 偶发卡顿：每约 10 秒一次连掉 20 帧（截图那样，约 0.67 秒）→ 每次只计 3 帧，90 秒都不降（旧计法 60 秒时掉帧率 3.3% > 1.5% 会降）
    // One-off stalls: 20 dropped frames in a row about every 10 s (like a screenshot, about 0.67 s) -> each counts 3, no step in 90 s (the old count reached 3.3% > 1.5% at 60 s and stepped down)
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 7000 * S3_SEC;
    for (int k = 0; k < 9; k++) { s3_n(20, D60); s3_n(580, F60); }
    CHECK(s3.level == 0, "偶发卡顿：每 10 秒连掉 20 帧、共 9 次 → 不降");
    // 频繁的短卡顿照常计：6 帧掉 + 6 帧正常反复（每段计 3 帧，计入的掉帧率 25%）→ 10 秒内降
    // Frequent short stalls still count: 6 dropped + 6 normal frames repeated (3 counted per run, a counted rate of 25%) -> steps down within 10 s
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 7500 * S3_SEC;
    for (int k = 0; k < 40; k++) { s3_n(6, D60); s3_n(6, F60); }
    CHECK(s3.level == 1, "频繁短卡顿：6 掉 6 好反复 12 秒 → 降到 1 档");
    // 长时间全掉帧：前 3 帧之后，连续满 1 秒起每帧都计 → 照样 5 窗内降（同上面的快降）
    // A long run of dropped frames: after the first 3, every frame counts once the run has lasted 1 s -> still steps down within 5 windows (as the fast-lowering case above)
    s3 = (scale3d_ctl){.max_level = 2}; s3_now = 8000 * S3_SEC;
    CHECK(s3_n(299, D60) == 0 && s3_n(1, D60) == 1, "长段掉帧：满 5 窗（10 秒）→ 降到 1 档，时刻不变");
    // Frames never shown (-1) on their own (R1, R2): a run of them counts only its first 3 frames and never escalates, and a 2 s window with no
    // frame on screen is neither judged nor counted as clean
    s3 = (scale3d_ctl){.max_level = 3}; s3_now = 8500 * S3_SEC;
    s3_n(600, F60); s3_n(600, -1);
    CHECK(s3.level == 0 && s3.nw == 5 && s3.good_run == 5, "S1: 10 s at 60 fps, then 10 s with nothing on screen: no step, the 5 shown windows kept, none added");
    s3 = (scale3d_ctl){.max_level = 3}; s3_now = 8600 * S3_SEC;
    s3_n(600, F60); s3_one(F60); s3_n(119, -1);
    CHECK(s3.level == 0, "S2: one shown frame then 119 not shown in a window: the run counts 3 (2.5%), no step (the old count was 63 of 600, 10.5%)");
    s3 = (scale3d_ctl){.max_level = 3}; s3_now = 8700 * S3_SEC;
    s3_n(600, F60); for (int i = 0; i < 300; i++) s3_one(i % 2 ? -1 : D60);
    CHECK(s3.level >= 1, "S3: a run that holds late frames on screen (33.4 ms) between not-shown ones is real load: steps down");
    // One refresh late on screens that are not multiples of 60 (S3D-8): 1.5 periods fall exactly between two refreshes, so timestamp jitter decided
    // whether a frame one refresh late counted; the 0.25 ms margin keeps it out, and two refreshes late still count
    s3 = (scale3d_ctl){.max_level = 2, .period_ms = 1000.0 / 72}; s3_now = 8800 * S3_SEC;
    CHECK(s3_n(1200, 20.84) == 0, "S5: 72 fps, frames one refresh late with 7 us of jitter (20.84 ms): not drops, no step");
    s3 = (scale3d_ctl){.max_level = 2, .period_ms = 1000.0 / 72}; s3_now = 8900 * S3_SEC;
    CHECK(s3_n(600, 27.778) >= 1, "S5: 72 fps, frames two refreshes late (27.778 ms): drops, steps down");
    s3 = (scale3d_ctl){.max_level = 2, .period_ms = 1000.0 / 82.5}; s3_now = 9000 * S3_SEC;
    CHECK(s3_n(1200, 18.19) == 0, "S5: 165 Hz screen at 82.5 fps, frames one refresh late (18.19 ms): not drops, no step");
    int a = s3_replay(0), b = s3_replay(1);
    printf("  （实玩第二段回放：慢帧均匀散开换级 %d 次，挤在一起换级 %d 次）\n", a, b);
    CHECK(a == 0 && b == 0, "动态比例：实玩第二段的慢帧序列（帧率 59+）不论散开还是挤在一起都不换级");
}
// Frame Drops test hooks in dm_3d_scale_feed and s3_cfg: DM_TEST_Q3D, DM_3D_SCALE_DYN_INJECT's + form and its quality-first bypass, dm_3d_scale_cfg.
// The feed and s3_cfg read their switches once, so each case runs in its own child with its own environment; the child's exit code is the level reached
// (0 = pass for the dm_3d_scale_cfg and scale3d rate cases). Expected values are worked out from the rules: the 20 s hold after entering a game
// (none while injecting), 1 s after each frame out of a game, 2 s windows, a step after 5 windows over 5% drops, a run of drops counting 3 frames until it lasts 1 s.
static int feed_n(int n, double iv) {   // n frames of iv ms (iv <= 0: a 60 fps frame's worth of time); one presented frame each
    for (int i = 0; i < n; i++) { t_now += (uint64_t)((iv > 0 ? iv : F60) * 1e6); g_frames++; dm_3d_scale_feed(iv); }
    return atomic_load(&g_scale3d_level);
}
static int child_feed(int kind, const char *q3d, const char *inj, int keep) {
    fflush(stdout); fflush(stderr); pid_t p = fork(); if (p < 0) return -1;
    if (!p) {
        child_kind = 100 + kind; signal(SIGALRM, abort_exit); alarm(10);
        unsetenv("DM_TEST_Q3D"); unsetenv("DM_3D_SCALE_DYN_INJECT");
        if (q3d) setenv("DM_TEST_Q3D", q3d, 1);
        if (inj) setenv("DM_3D_SCALE_DYN_INJECT", inj, 1);
        dm_3d_quality_mode_set(keep); t_now = 1000 * S3_SEC; g_frames = 5000;
        if (kind == 0) _exit(feed_n(1500, D60));                     // 20 s hold (about 600 frames), then 5 windows of drops (300 frames)
        if (kind == 1) { int a = feed_n(1100, F60); _exit(a ? 90 : feed_n(600, F60)); }   // + form: frames 0-1099 before the window are clean, then injected drops
        if (kind == 2) _exit(feed_n(400, F60));                      // plain injection from frame 0: no entry hold, a step after 5 windows (300 frames)
        if (kind == 3) {                                             // dm_3d_scale_cfg: DM_3D_SCALE read once
            setenv("DM_3D_SCALE", "0.85", 1); float a = dm_3d_scale_cfg(); setenv("DM_3D_SCALE", "0.6", 1); float b = dm_3d_scale_cfg();
            _exit(fabsf(a - 0.85f) < 1e-6f && fabsf(b - 0.85f) < 1e-6f ? 0 : 1);
        }
        if (kind == 4) {   // + form after frames out of a game: each holds judging 1 s, so the first judged frame is the 60th in the game
            // Frames 0-89 from there are injected (3 s): judged in full, the run of drops counts in full past its first second (about 64 drops
            // in the first 5 windows, > 5%), and the controller steps near in-game frame 570. Counted from the first in-game frame instead, only
            // the last 31 are judged: a run that counts about 5 drops (under 1%), so it never steps
            t_ingame = 0; feed_n(10, F60); t_ingame = 1; _exit(feed_n(700, F60));
        }
        if (kind == 5 || kind == 6) {   // the drop rates of a step are dropped when the level goes back to 0 without a step: Keep (5), a new 3D Resolution (6)
            int a = feed_n(1500, D60); float r = atomic_load(&g_s3_r10);
            if (kind == 5) dm_3d_quality_mode_set(1); else g_s3_env = 0.75f;   // 6: as if DM_3D_SCALE had said 0.75 (s3_cfg reads it once)
            feed_n(1, F60);
            _exit(a < 1 || r <= 0 ? 2 : atomic_load(&g_scale3d_level) == 0 && atomic_load(&g_s3_r10) == 0 && atomic_load(&g_s3_r60) == 0 ? 0 : 1);
        }
        if (kind == 7) {   // a step's drop rates go to one scale3d event: the first rebuild after the step takes them (s3_ev_rates), the next one reads 0
            int a = feed_n(1500, D60); double r10, r60, s10, s60; s3_ev_rates(&r10, &r60); s3_ev_rates(&s10, &s60);
            _exit(a < 1 ? 2 : r10 > 5 && s10 == 0 && s60 == 0 ? 0 : 1);
        }
        _exit(99);
    }
    int st; if (waitpid(p, &st, 0) != p || !WIFEXITED(st)) return -1;
    return WEXITSTATUS(st);
}
static void test_scale3d_hooks(void) {
    int r;
    r = child_feed(0, "0", NULL, 1); printf("  (DM_TEST_Q3D=0 with Keep saved: level %d)\n", r);
    CHECK(r >= 1, "DM_TEST_Q3D=0: the controller runs although the setting is Keep, and steps down on drops");
    CHECK(child_feed(0, NULL, NULL, 1) == 0, "control: Keep with no override never steps");
    CHECK(child_feed(0, "1", NULL, 0) == 0, "DM_TEST_Q3D=1: Lower saved, forced to Keep, never steps");
    r = child_feed(1, NULL, "+1100-100000000", 0); printf("  (DM_3D_SCALE_DYN_INJECT=+1100-…: exit %d; 90 = stepped before the window)\n", r);
    CHECK(r >= 1 && r != 90, "DM_3D_SCALE_DYN_INJECT=+a-b: counted from the first judged frame (frame 5001 here), so nothing is injected before it and drops after it step down");
    r = child_feed(2, NULL, "0-100000000", 1); printf("  (DM_3D_SCALE_DYN_INJECT=0-… with Keep saved: level %d)\n", r);
    CHECK(r >= 1, "DM_3D_SCALE_DYN_INJECT: Keep does not stop the controller while the injection switch is set");
    CHECK(child_feed(2, "1", "0-100000000", 0) == 0, "DM_TEST_Q3D=1 wins over the injection bypass");
    CHECK(child_feed(3, NULL, NULL, 0) == 0, "dm_3d_scale_cfg: DM_3D_SCALE read once (0.85, then 0.6 set later is ignored)");
    r = child_feed(4, NULL, "+0-89", 0); printf("  (DM_3D_SCALE_DYN_INJECT=+0-89 after frames out of a game: level %d)\n", r);
    CHECK(r >= 1, "DM_3D_SCALE_DYN_INJECT=+a-b: latched at the first judged frame, not at the first in-game frame (still held 1 s by the frames out of a game)");
    r = child_feed(2, "x", "0-100000000", 1); printf("  (DM_TEST_Q3D=x with the injection and Keep saved: level %d)\n", r);
    CHECK(r >= 1, "DM_TEST_Q3D that is not 0 or 1 is ignored, and the injection bypass of Keep still applies");
    r = child_feed(5, NULL, NULL, 0); printf("  (Keep after a step: exit %d; 1 = drop rates kept, 2 = no step)\n", r);
    CHECK(r == 0, "scale3d rates: Keep puts the level back to 0 and clears the drop rates of the last step");
    r = child_feed(6, NULL, NULL, 0); printf("  (new 3D Resolution after a step: exit %d; 1 = drop rates kept, 2 = no step)\n", r);
    CHECK(r == 0, "scale3d rates: a new 3D Resolution puts the level back to 0 and clears the drop rates of the last step");
    r = child_feed(7, NULL, NULL, 0); printf("  (rates read twice after a step: exit %d)\n", r);
    CHECK(r == 0, "scale3d rates: the first rebuild after a step reports its drop rates, a later rebuild with no step behind it reports 0");
}
// Frame Drops feed (dm_3d_scale_feed) in the parent, after the forked hook cases: frames never shown, gaps in the presents and loading screens.
// Expected values from the rules: 20 s hold on entering a game, 1 s per frame out of a game or hidden, 3 s once the picture is visible again,
// a gap over 0.5 s pauses judging 3 s and keeps the history
static void feed_reset(void) {
    g_s3f = (s3_feed_state)S3_FEED_INIT; atomic_store(&g_3d_quality_mode, 0); atomic_store(&g_scale3d_level, 0); atomic_store(&g_scale3d_resumed, 0); s3_rates_clear();
    t_now = 10000 * S3_SEC; t_hidden = t_load = 0; t_ingame = 1;
}
static void test_feed(void) {
    feed_reset();
    CHECK(feed_n(1500, F60) == 0, "F1: 25 s in a game at 60 fps: no step");
    t_hidden = 1; int lv = feed_n(900, D60);
    printf("  (F1: 30 s of slow frames while hidden: level %d, %d windows)\n", lv, g_s3f.c.nw);
    CHECK(lv == 0 && g_s3f.c.nw == 0, "F1: frames while presents are hidden are not judged: no step, no windows");
    t_hidden = 0; feed_n(1, F60);
    CHECK(g_s3f.c.hold_until == t_now + 3 * S3_SEC, "F1: the picture visible again holds judging 3 s");
    feed_reset(); feed_n(1500, F60);
    CHECK(feed_n(900, D60) >= 1, "F1 control: the same slow frames shown step down");
    feed_reset(); feed_n(1500, F60);
    int n0 = g_s3f.c.nw, g0 = g_s3f.c.good_run; uint64_t h0 = g_s3f.c.hold_until;
    t_now += 400000000ull; feed_n(1, F60);
    CHECK(g_s3f.c.hold_until == h0, "F2: a 0.4 s gap in the presents is not a pause");
    t_now += 2 * S3_SEC; feed_n(1, F60);
    printf("  (F2: after a 2 s gap: hold %+.3f s, windows %d -> %d, clean run %d -> %d)\n", ((double)g_s3f.c.hold_until - (double)t_now) / 1e9, n0, g_s3f.c.nw, g0, g_s3f.c.good_run);
    CHECK(g_s3f.c.hold_until == t_now + 3 * S3_SEC && g_s3f.c.nw == n0 && g_s3f.c.good_run == g0 && atomic_load(&g_scale3d_level) == 0,
          "F2: a 2 s gap pauses judging 3 s and keeps the windows and the clean run");
    feed_reset(); feed_n(1500, F60);
    t_load = 1; lv = feed_n(600, D60);
    CHECK(lv == 0 && g_s3f.c.nw == 0, "F3: slow frames under a loading screen are not judged");
    t_load = 0; feed_n(1, F60);
    CHECK(g_s3f.c.hold_until == t_now + 20 * S3_SEC, "F3: after a loading screen, judging waits 20 s, as on entering a game");
    // F4: Keep, then Lower again, starts from fresh history (S3D-10). Drops until the first step, then 3 s held and 4 windows of drops (330 frames
    // of 33.4 ms), so the history holds 4 stale windows, one short of the next step
    feed_reset(); feed_n(1500, F60);
    { int k = 0; while (feed_n(1, D60) == 0 && ++k < 2000) {} }
    CHECK(feed_n(330, D60) == 1 && g_s3f.c.nw == 4, "F4: Lower steps down on drops; 11 s later 4 windows of drops are held");
    dm_3d_quality_mode_set(1);
    CHECK(feed_n(1, D60) == 0, "F4: Keep puts the level back to 0");
    dm_3d_quality_mode_set(0); feed_n(1, D60);
    printf("  (F4: back to Lower: %d windows, need_good %d, last_up %llu, hold %+.3f s)\n", g_s3f.c.nw, g_s3f.c.need_good, (unsigned long long)g_s3f.c.last_up, ((double)g_s3f.c.hold_until - (double)t_now) / 1e9);
    CHECK(g_s3f.c.nw == 0 && g_s3f.c.need_good == 0 && g_s3f.c.last_up == 0 && g_s3f.c.hold_until == t_now + 3 * S3_SEC, "F4: back to Lower: history cleared and judging held 3 s");
    CHECK(feed_n(119, D60) == 0, "F4: 4 s of drops after that: no step on stale windows");
    // F4b: the game entered in Keep (the Mac's default) 25 s ago, then Lower: the 3 s of the switch, not a fresh 20 s entry hold
    feed_reset(); dm_3d_quality_mode_set(1); feed_n(1500, F60);
    dm_3d_quality_mode_set(0); feed_n(1, F60);
    printf("  (F4b: Lower after 25 s in a game in Keep: hold %+.3f s)\n", ((double)g_s3f.c.hold_until - (double)t_now) / 1e9);
    CHECK(g_s3f.c.hold_until == t_now + 3 * S3_SEC, "F4b: game entered in Keep, then Lower: judging held 3 s, not 20");
    // F4c: the game entered in Keep 5 s ago, then Lower: the entry hold set in Keep still runs out 20 s after entering
    feed_reset(); dm_3d_quality_mode_set(1); feed_n(1, F60);
    uint64_t h_entry = g_s3f.c.hold_until;
    CHECK(h_entry == t_now + 20 * S3_SEC, "F4c: entering a game in Keep sets the 20 s entry hold");
    feed_n(299, F60); dm_3d_quality_mode_set(0); feed_n(1, F60);
    CHECK(g_s3f.c.hold_until == h_entry, "F4c: Lower 5 s after entering in Keep: judging waits for the rest of the entry hold");
    dm_3d_quality_mode_set(0);
    // F5: the feed judges against the pacer's frame period (nvn_frame_period_ms), not one derived from the screen (S3D-8)
    feed_reset(); t_period = 1000.0 / 72; feed_n(1500, 13.889);
    CHECK(feed_n(900, 20.84) == 0, "F5: 72 fps, frames one refresh late: no step");
    feed_reset(); t_period = 1000.0 / 72; feed_n(1500, 13.889);
    CHECK(feed_n(600, 27.778) >= 1, "F5: 72 fps, frames two refreshes late: steps down");
    feed_reset(); t_period = 1000.0 / 120;
    CHECK(feed_n(2500, 8.333) == 0, "F5: 120 fps (DM_PRESENT_HZ=120): no step");
    CHECK(feed_n(900, 16.667) >= 1, "F5: 120 fps falling to 60: frames two periods long step down");
    feed_reset(); feed_n(1500, F60); t_period = 1000.0 / 30; feed_n(1, 33.333);
    CHECK(g_s3f.c.hold_until == t_now + 2 * S3_SEC, "F5: the pacer's period changes (power saving 30 fps): judging held 2 s");
    t_period = 1000.0 / 60;
}
// DM_AA_MODE parsing (aa_env_parse): only 0, 1, 2 and off are taken; 3-5 crash the game in its SMAA pass, anything else is malformed
static void aa_parse_cases(void) {
    CHECK(aa_env_parse(NULL) == -1 && aa_env_parse("") == -1, "DM_AA_MODE unset or empty: the picture setting decides (-1)");
    CHECK(aa_env_parse("off") == -3, "DM_AA_MODE=off: leave the byte to the game (-3)");
    CHECK(aa_env_parse("0") == 0 && aa_env_parse("1") == 1 && aa_env_parse("2") == 2, "DM_AA_MODE=0 / 1 / 2: forced");
    CHECK(aa_env_parse("3") == -4 && aa_env_parse("4") == -4 && aa_env_parse("5") == -4, "DM_AA_MODE=3 / 4 / 5: refused, they crash the game (-4)");
    CHECK(aa_env_parse("6") == -5 && aa_env_parse("2 ") == -5 && aa_env_parse("smaa") == -5 && aa_env_parse("-1") == -5 && aa_env_parse("OFF") == -5 && aa_env_parse("02") == -5,
          "DM_AA_MODE=6 / '2 ' / smaa / -1 / OFF / 02: malformed (-5), no trimming, case-sensitive");
}
// aa_tick against a fake main module whose renderer has the AA mode byte at +0x6614, starting at init (1 = the console config): each case in a forked child,
// because aa_tick reads DM_AA_MODE once into a static. A case that expects a write starts from a different value, so its result proves the write happened.
// Returns the byte the child saw after one tick, or -1 when the child failed. scale3d_tick isn't called (its output size reads 0)
static int aa_case(const char *env, int want, uint64_t frames, int init) {
    fflush(stdout); pid_t p = fork(); if (p < 0) return -1;
    if (!p) {
        signal(SIGALRM, abort_exit); alarm(10);
        if (env) setenv("DM_AA_MODE", env, 1); else unsetenv("DM_AA_MODE");
        uint8_t *base = mmap(NULL, 0x3200000, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0); if (base == MAP_FAILED) _exit(255);
        uint8_t *renderer = calloc(1, 0x7000); renderer[0x6614] = (uint8_t)init;
        *(uintptr_t *)(base + 0x31e0848) = (uintptr_t)renderer;
        memset(&g_mod[0], 0, sizeof g_mod[0]); strcpy(g_mod[0].name, "main"); g_mod[0].base = base; g_nmod = 1;
        g_frames = frames; g_aa_want = want;
        aa_tick();
        _exit(renderer[0x6614]);
    }
    int st; if (waitpid(p, &st, 0) != p || !WIFEXITED(st) || WEXITSTATUS(st) == 255) return -1;
    return WEXITSTATUS(st);
}
static void aa_tick_cases(void) {
    CHECK(aa_case(NULL, 2, 0, 1) == 1, "aa_tick: before frame 30 the byte stays (1)");
    CHECK(aa_case(NULL, 2, 30, 1) == 2, "aa_tick: the picture setting's SMAA (2) is written from frame 30");
    CHECK(aa_case(NULL, 1, 30, 0) == 1, "aa_tick: the picture setting's FXAA (1) is written over 0");
    CHECK(aa_case(NULL, 1, 0, 0) == 0, "aa_tick: ... but not before frame 30 (0 stays)");
    CHECK(aa_case("off", 2, 30, 1) == 1, "aa_tick: DM_AA_MODE=off leaves the byte to the game");
    CHECK(aa_case("3", 2, 30, 1) == 2, "aa_tick: DM_AA_MODE=3 is refused (it crashes the game); the picture setting decides (2)");
    CHECK(aa_case("smaa", 2, 30, 1) == 2, "aa_tick: a malformed DM_AA_MODE is ignored; the picture setting decides (2)");
    CHECK(aa_case("0", 2, 30, 1) == 0, "aa_tick: DM_AA_MODE=0 forces no anti-aliasing");
    CHECK(aa_case("1", 2, 30, 0) == 1, "aa_tick: DM_AA_MODE=1 forces FXAA over the picture setting's SMAA");
    CHECK(aa_case("2", 1, 30, 1) == 2, "aa_tick: DM_AA_MODE=2 beats the picture setting");
}
int main(void) {
    aa_parse_cases();
    aa_tick_cases();   // first: aa_tick latches DM_AA_MODE into a static on its first call (every h_oe_TryPopMsg runs it), so the forked cases need an unlatched parent
    test_scale3d();
    // The hook cases fork, and each child inherits the parent's feed state: keep them before any parent-side call to dm_3d_scale_feed, s3_cfg,
    // dm_3d_scale_cfg or h_oe_TryPopMsg (which reaches s3_cfg through scale3d_tick). Those latch the switches (pthread_once) and the feed's statics.
    test_scale3d_hooks();
    test_feed();   // parent-side feed cases: after the forked hooks
    unsetenv("DM_OE_SCRIPT"); reset();
    CHECK(empty(), "初始空队列：返回false且不改输出");
    dm_focus_set(1); dm_set_opmode(1); CHECK(empty(), "相同状态不发通知");
    dm_focus_set(3); CHECK(h_oe_GetFocus() == 3, "消费前即可查询后台状态3");
    CHECK(pop_is(15) && empty(), "后台变化通知15恰一次");
    dm_focus_set(2); dm_focus_set(1);
    CHECK(pop_is(15) && empty() && h_oe_GetFocus() == 1, "未消费的失焦/恢复合并，查询最终焦点1");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1;
    dm_focus_set(2); dm_set_opmode(0); dm_focus_set(3); dm_set_opmode(1);
    CHECK(pop_is(15) && pop_is(30) && pop_is(31) && empty(), "三类首次排位FIFO=15,30,31，重复不挪位");
    CHECK(h_oe_GetFocus() == 3 && h_oe_GetOpMode() == 1 && h_oe_GetPerfMode() == 1, "重复通知不保存陈旧值，查询最新3/1/1");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1;
    dm_set_opmode(0); dm_focus_set(2); dm_set_opmode(1);
    CHECK(pop_is(30) && pop_is(31) && pop_is(15) && empty(), "模式先变化时FIFO=30,31,15，成对顺序不变");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1;
    dm_focus_set(2); CHECK(pop_is(15), "先弹出焦点通知");
    dm_set_opmode(0); dm_focus_set(1);
    CHECK(pop_is(30) && pop_is(31) && pop_is(15) && empty(), "弹出后的恢复再次通知并排在待取模式消息之后");
    CHECK(h_oe_GetFocus() == 1, "恢复后的当前焦点=1");
    reset(); dm_set_opmode(0);
    CHECK(empty() && h_oe_GetOpMode() == 0, "通知关闭只更新状态、不入队");
    h_oe_SetOpModeNtf(0x100); h_oe_SetPerfModeNtf(0x101); dm_set_opmode(1);
    CHECK(pop_is(31) && empty(), "通知bool只读低8位，性能单开只发31");
    h_oe_SetOpModeNtf(0x101); h_oe_SetPerfModeNtf(0x100); dm_set_opmode(0);
    CHECK(pop_is(30) && empty(), "运行模式单开只发30");
    reset(); mq_push(16); mq_push(16);
    CHECK(pop_is(16) && pop_is(16) && empty(), "逐次事件16不合并，保留两次FIFO");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1; dm_set_opmode(0);
    CHECK(pop_is(30), "模式对中先消费30，31尚未消费");
    dm_set_opmode(1);
    CHECK(pop_is(31) && pop_is(30) && empty() && h_oe_GetOpMode() == 1, "消费跨新变化：旧31保留排位，已弹30重新排队，最终模式1");
    CHECK(child_burst(0), "34次焦点变化跨旧32槽，不终止且最终恢复1/一条15");
    CHECK(child_burst(1), "17次模式变化跨旧32槽，不终止且最终0/30,31");
    CHECK(child_burst(2), "两生产者并发，各类恰一条、30先于31、最终焦点1/模式0");
    reset(); g_ntf_opmode = g_ntf_perfmode = 1; int rotated = 1;
    for (int i = 0; i < 31; i++) { dm_focus_set(2 - i % 2); rotated &= pop_is(15) && empty(); }
    CHECK(rotated, "31次逐条消费，把环头推进到尾槽");
    dm_focus_set(1); dm_set_opmode(0); dm_focus_set(3); dm_set_opmode(1);
    CHECK(pop_is(15) && pop_is(30) && pop_is(31) && empty(), "跨32槽回绕后仍按15,30,31去重并保持首次顺序");
    CHECK(child_burst(3), "消费者弹出后、查询前发生新变化：新恢复不漏通知，最终焦点1/模式0");
    printf("== oe %d 项，失败 %d ==\n", checks, fails); return fails != 0;
}
